macro.dbt_assertions.default___get_uniqu.macro_sql:
{%- macro default___get_unique_assertions(unique_columns) %}

{%- set result = {} %}
{%- set layered_unique_columns = dbt_assertions._extract_columns(unique_columns) %}

{#- Iterate through columns by layer #}
{%- for parent_column, layer_unique_columns in layered_unique_columns.items() %}

    {%- set unique_columns = layer_unique_columns['columns'] %}
    {%- set depends_on = layer_unique_columns['depends_on'] %}


    {#- Create unique assertions on the first layer #}
    {%- if parent_column is none %}

        {%- do result.update({
                'unique': {
                    'description': 'Row must be unique over the unique keys.',
                    'expression': '1 = COUNT(1) OVER(PARTITION BY ' 
                        ~ ', '.join(unique_columns) ~ ')',
                }
            })
        %}

    {#- Create unique assertions on the other layers (more complex) #}
    {%- else %}

        {#- NOT EXISTS part #}
        {%- set expression = ['NOT EXISTS (\n    SELECT 1'] %}

        {#- Joins parts #}
        {%- for layer_dependence_key in depends_on + [parent_column] %}
            {%- do expression.append(
                '\n    ' ~ ('FROM' if loop.first else 'CROSS JOIN')
                )
            %}
            {%- do expression.append(
                ' UNNEST(' ~ layer_dependence_key ~') ' ~ layer_dependence_key
                )
            %}
        {%- endfor %}

        {#- QUALIFY parts #}
        {%- do expression.append(
            '\n    QUALIFY 1 < COUNT(1) OVER(\n    PARTITION BY'
            )
        %}
        {%- for layer_dependence_key in depends_on + [parent_column] %}

            {%- set loop_last_layer = loop.last %}
            {%- for unique_column in layered_unique_columns[layer_dependence_key]['columns'] %}
                {%- do expression.append(
                    '\n        ' ~ layer_dependence_key ~ '.' ~ unique_column
                    )
                %}
                {%- do expression.append(
                    '' if loop_last_layer and loop.last else ','
                    )
                %}

            {%- endfor %}
        {%- endfor %}

        {#- Close parenthesis #}
        {%- do expression.append('))') %}

        {%- do result.update({
                '.'.join(depends_on + [parent_column]) ~'__unique': {
                    'description': 'Items must be unique within'
                        ~ '.'.join(parents_columns) ~ ' in the row.',
                    'expression': ''.join(expression),
                }
            })
        %}

    {%- endif %}

{%- endfor %}

{{- return(result) }}

{%- endmacro %}

macro.dbt_assertions._extract_columns.macro_sql:
{%- macro _extract_columns(columns, parent_column=none, depends_on=none) %}
{#-
    Extracts a flattened representation of columns hierarchy.

    Args:
        columns (list): Column names or dict of nested structures.
        depends_on (optional[list]): Dependencies of the current columns.

    Returns:
        dict: A dictionary with keys representing the columns and values
            as dictionaries containing columns and their dependencies.

    Example:
        columns = [
            "key_01",
            "key_02",
            {
                "nested_field_1": ["sub_key_11", "sub_key_12"],
                "nested_field_2": [
                    "sub_key_21",
                    {
                        "nested_field_3": ["sub_key_31", "sub_key_32"]
                    }
                ]
            },
            {
                "nested_field_4": ["sub_key_41", "sub_key_42"],
            }
        ]

        _extract_columns(columns) returns:
        {
            none: {
                'columns': ['key_01', 'key_02'],
                'depends_on': []
            },
            'nested_field_1': {
                'columns': ['sub_key_11', 'sub_key_12'],
                'depends_on': []
            },
            'nested_field_2': {
                'columns': ['sub_key_21'],
                'depends_on': ['nested_field_1']
            },
            'nested_field_3': {
                'columns': ['sub_key_31', 'sub_key_32'],
                'depends_on': ['nested_field_1', 'nested_field_2']
            },
            'nested_field_4': {
                'columns': ['sub_key_41', 'sub_key_42'],
                'depends_on': []
            }
        }
#}

{%- if columns | length == 0 %}
    {{- return({}) }}
{%- endif %}

{%- set result = {parent_column: {'columns': [], 'depends_on': depends_on or []}} %}
{#- Iterate through columns #}
{%- for column in columns %}

    {#- Process flat keys (to the current layer) #}
    {%- if column is string %}
        {%- do result[parent_column]['columns'].append(column) %}

    {#- Process nested repeated keys (from the deeper layers) #}
    {%- elif column is mapping %}

        {#- Depth can be horizontal and vertical #}
        {%- for nested_column, sub_columns in column.items() %}

            {%- do result.update(dbt_assertions._extract_columns(
                    columns=sub_columns,
                    parent_column=nested_column,
                    depends_on=depends_on + [parent_column] if depends_on is not none else [],
                )
            ) %}

        {%- endfor %}

    {%- endif %}

{%- endfor %}

{{- return(result) }}

{%- endmacro %}

